		}
		ga('send',
			{
				hitType: 'event',
				eventCategory: 'News Flash',
				eventAction: 'News Flash - ' + text,
				eventLabel: window.location.href
			});
	}
	if (target.hasClass('widgetQuickLinksLink') || target.find('.widgetQuickLinksLink').length) {
